<?php
declare(strict_types=1);
require_once __DIR__.'/db.php';
function ensure_registration_schema():void{db()->exec('CREATE TABLE IF NOT EXISTS registration_plans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(500) NOT NULL,description TEXT NULL,primary_pdf VARCHAR(500) NULL,primary_name VARCHAR(255) NULL,lower_pdf VARCHAR(500) NULL,lower_name VARCHAR(255) NULL,upper_pdf VARCHAR(500) NULL,upper_name VARCHAR(255) NULL,status ENUM("draft","published") NOT NULL DEFAULT "published",created_by INT UNSIGNED NULL,updated_by INT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_registration_created_by FOREIGN KEY(created_by) REFERENCES admin_users(id) ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT fk_registration_updated_by FOREIGN KEY(updated_by) REFERENCES admin_users(id) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci');}
